## Summary

Implement writing events to the state branch when Store is in StateBranch mode.

## Implementation

In `src/store.rs`:

```rust
impl Store {
    /// Append event to bug file on state branch
    fn append_to_state_branch(&self, event: &Event) -> Result<()> {
        let bug_id = &event.bug_id;
        let path = format!(".docket/bugs/{}/{}.jsonl", &bug_id[..1], bug_id);

        // 1. Read current content (may not exist)
        let current = jj::read_state_file(&path).unwrap_or_default();

        // 2. Append new event
        let event_json = serde_json::to_string(event)?;
        let new_content = if current.is_empty() {
            format!("{}\n", event_json)
        } else {
            format!("{}{}\n", current, event_json)
        };

        // 3. Write atomically via jj
        // Create child of docket-state, write file, squash back
        jj::write_to_state_branch(&path, &new_content, &format!("docket: update {}", bug_id))?;

        Ok(())
    }

    // Update append_event to dispatch
    pub fn append_event(&self, event: &Event) -> Result<()> {
        match &self.mode {
            StoreMode::FileSystem { .. } => self.append_event_filesystem(event),
            StoreMode::StateBranch { .. } => self.append_to_state_branch(event),
        }
    }
}
```

Add to jj helpers:
