pub fn write_to_state_branch(path: &str, content: &str, message: &str) -> Result<()> {
    // 1. jj new docket-state --no-edit
    // 2. jj file write <path> --content <content>
    // 3. jj describe -m <message>
    // 4. jj squash --into docket-state
}
```

